from crewai import Task
 
from agent.activity_agent import activity_planner
 
 
def create_activity_task(
    event_name,
    audience,
    idea_task
):
 
    activity_task = Task(
 
        description=(
 
            f"Plan activities for the event: {event_name}."
 
            f"The target audience is {audience}."
 
            "Use the event theme generated by the Idea Generator."
 
            "Create exactly four simple and engaging activities."
 
            "Each activity should be suitable for the target audience."
 
            "Provide a short explanation of each activity."
 
        ),
 
        expected_output=(
 
            "Exactly four numbered event activities "
            "with a short description of each activity."
 
        ),
 
        agent=activity_planner,
 
        context=[idea_task]
    )
 
    return activity_task